local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["4101db7d29d8defd"] = { "%s si addormenta all'improvviso.", "." },
  ["4103048a3424919d"] = { "A dopo, Corbett, e salutami la signora!", "." },
  ["41097e03a486f722"] = { "Il varco si aprirà lì, sopra il Lago Elune'ara. Preparati, {name}. L'ingresso di Eranikus nel nostro mondo porterà caos e conflitto.", "." },
  ["410d10f12875cbfb"] = { "%s si ritrae per il dolore mentre il Judgement of Righteousness lo investe!", "." },
  ["4113ed2d1aab6a5c"] = { "Benvenut<o/a> alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧, {class}!\n\nMi chiamo Kerri Hicks e ti stringerei la mano, ma temo che te la romperei, perché sono la donna più forte del mondo!", "." },
  ["4119001eb85453a6"] = { "si sta congelando!", "." },
  ["411966193410af70"] = { "Non c'è niente di meglio di un bel fuoco scoppiettante in una notte fresca, con buoni amici e birra dei nani.", "." },
  ["4119bf88657f9ea3"] = { "È tutto raccolto, {class}. Tutto viene trasportato a ⟦Silithus=Silitus⟧ per i preparativi finali e dovrebbe arrivare entro $2113w giorni. Tutte le nostre forze riunite attendono l'<eroe/eroina> che completerà la riunificazione dello Scettro delle Sabbie Mutevoli, suonerà il gong e darà inizio alla Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧.", "." },
  ["412869af723e0ee0"] = { "Oh, va bene! Ecco qui, {name}. È il minimo che possa fare per tutto l'aiuto che mi hai dato.", "." },
  ["4129c4a6d1659b8c"] = { "Più di quanti vorrei, temo. Siamo tormentati da una banda di briganti accampati in una grotta a nord, e il culto di Al'Aketh ha appena preso Falaath Village, a sud di qui. Mi fido di ogni pacificatore e di ogni cittadino, ma siamo troppo pochi per tenere il villaggio al sicuro.\r\n\nSe il culto decide di continuare a espandersi fin qui, c'è poco che possiamo fare per fermarlo.", "." },
  ["412ee818cb0e07b2"] = { "Lo sai che nei canali ci sono dei crocolischi? Li hanno portati dalla palude come animali da compagnia, ma poi sono stati gettati nei canali.", "." },
  ["4136f5eb378d06bd"] = { "Hai provato quella Thunderbrew Lager? È roba buona!", "." },
  ["4138f29ed5a62cff"] = { "Non sei male, ma lascia che ti mostri qualche trucco che potrebbe tornarti utile.", "." },
  ["414ab8a60d8dfcd5"] = { "Il cartellino su questo regalo dice: \"Dai 20 anni in su.\"", "." },
  ["414e345f6ddfbccb"] = { "Sei ciec<o/a>, piccol<o/a>? Shayis è proprio qui fuori.", "." },
  ["414e95aa837aad76"] = { "E così i cavalieri si pararono davanti all'⟦Horde=Orda⟧ alla carica e tennero la posizione mentre mille orchi furiosi attraversavano la valle.", "." },
  ["414eeff95ccafbab"] = { "Chi sarebbe tanto sciocco da entrare nella torre del Gran Caposquadra?", "." },
  ["415c414b96370a16"] = { "Lo spirito dell'orso ti osserva con sguardo calmo e sereno. Senti una voce parlarti come se provenisse dall'orso, ma la creatura non dà alcun segno di parlare.\n\n«Salute, <mio/mia> giovane <amico/amica>. Se sei qui in cerca di una guida, forse posso aiutarti a trovare ciò che cerchi.»", "." },
  ["41600e69a4113ed5"] = { "Per quale posto ti servono indicazioni?", "." },
  ["41654fadc969bd8a"] = { "Sì, padrone!", "." },
  ["4166a9cd9b331dd2"] = { "A volte stupisco perfino me!", "." },
  ["4167d3e4e440a90f"] = { "Reverito", "." },
  ["416a8bcfb60d0594"] = { "La ⟦Might of Kalimdor=Forza di Kalimdor⟧ ha vinto! Le ultime forze qiraji sono sconfitte e si ritirano nell'antica città-fortezza di ⟦Ahn'Qiraj=Ahn'qiraj⟧. I Qiraji Resonating Crystal sparsi per Kalimdor svaniscono con la stessa rapidità con cui sono apparsi, lasciando dietro di sé solo terra squarciata.", "." },
  ["416ac29ea9638118"] = { "Salute, Antico. Ho fatto tutto ciò che mi è stato chiesto. Ora ti chiedo di concedermi Rhok'delar.", "." },
  ["4171b31c10a3d84c"] = { "Già, non voglio essere qui se Myzrael si sveglia. Dicono che abbia un caratteraccio...", "." },
  ["4176768b1f990b55"] = { "Se provi a fallire e ci riesci, cosa hai appena fatto?", "." },
  ["41791003aed682b3"] = { "La forza del corpo è la potenza e la rapidità dell'azione. Devi mantenerti in forma in ogni momento, sia nel fisico sia nella mente. La mole dell'orso mette in risalto la sua forza, perché in combattimento è un nemico feroce. La sua mole, però, nasconde un'agilità flessuosa e una mente acuta. Sono sorprese che userai a tuo vantaggio.\n\nDevi affidarti alla forza del corpo dell'orso per padroneggiare la via dell'Artiglio.", "." },
  ["417c3914fbe2a7d4"] = { "Infedeli!", "." },
  ["417ca41d329c2ea4"] = { "L'anziana Corno Nero si trova tra le rocce rosse di Orgrimmar.", "." },
  ["417e2f944db26dba"] = { "Il nostro Signore ci ordina di prepararci alla guerra!", "." },
  ["417e61545d5259ed"] = { "Che la Luce guidi il tuo cammino e ti aiuti nei tuoi viaggi. Se ti serve aiuto mentre guardi la merce, sono proprio qui.", "." },
  ["4181248cdc7be917"] = { "Ho abbastanza rifornimenti per promuovere le nostre truppe a campioni.", "." },
  ["4183f3ce4ab13af5"] = { "Mi serve un altro ⟦Argent Dawn Commission=Distintivo dell'Alba d'Argento⟧.", "." },
  ["4193341a2734fcda"] = { "%s posa le assi di legno raffinato.", "." },
  ["4193dc8e4b4a9b05"] = { "Qui al porto vedo andare e venire personaggi interessanti. Stai in guardia, {name}. Non si sa mai di chi fidarsi, con tutti i loschi traffici che ci sono da queste parti...", "." },
  ["4199fce677fce283"] = { "Dovrai avere un po' di pazienza, {name}. Ho il mio Spybot là dentro che lavora a una faccenda molto delicata. Sono da te tra un secondo.\n\nAh, e fammi un favore: cerca di non farti vedere da Lescovar... stiamo per tendergli un'imboscata.", "." },
  ["419b517ea6dc2ef0"] = { "I cimiteri della ⟦Alterac Valley=Valle d'Alterac⟧ sono il luogo dove le anime dei defunti trovano riposo e conforto. Se muori, il tuo spirito vagherà fino al cimitero più vicino controllato dalla nostra parte.", "." },
  ["41a8b4ed9d3be8f3"] = { "Vorrei sapere dove trovare un istruttore di professioni qui vicino.", "." },
  ["41aeed650c795c10"] = { "Presto, {name}! Dobbiamo trovare un riparo!", "." },
  ["41c28d4c93a11143"] = { "Enormi cristalli risonanti qiraji squarciano la crosta terrestre di Kalimdor. Creature colossali di ossidiana irrompono dalla terra appena spaccata.", "." },
  ["41c56b032ee85f7c"] = { "Quali richieste?", "." },
  ["41cd51d7e2e5dc22"] = { "No!!! Siate maledetti, intrusi! Gli eserciti del Re dei Lich vi daranno la caccia. Non sfuggirete al vostro destino...", "." },
  ["41df1882b13c1bb4"] = { "Tre minuti alla fine: sento l'energia che comincia ad accumularsi! Tenete salda la difesa!", "." },
  ["41dfbe0b2c3d9763"] = { "Addio, amico mio.", "." },
  ["41e3db8b69356c4d"] = { "L'avete vista? Io Darcy non l'ho vista. Chissà dov'è stasera.", "." },
  ["41e715c90c4ca33b"] = { "Eroi della Stirpe? ⟦C'Thun=C'thun⟧ va bandito! Possiamo assisterti, mortale!", "." },
  ["41e8c194ea85d39d"] = { "Ops!", "." },
  ["41edfcd55e90ace4"] = { "<Benvenuto/Benvenuta> allo ⟦Steelgrill's Depot=Scalo di Grigliafredda⟧!", "." },
  ["41f46cb4b9c62073"] = { "Conoscerai il rifugio che solo la morte può offrire...", "." },
  ["41f59cfe906685ed"] = { "Ah, guarda che ora è! Devo tornare al mio posto... lassù.", "." },
  ["41fa5c689eb6df14"] = { "Oh, adesso si fa sul serio! Pensavi che anch'io fossi senza compagnia, eh?!", "." },
})
